package com.lovemaptually.entity;
import jakarta.persistence.*;import lombok.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import static com.lovemaptually.entity.Enums.*;
@Entity @Table(name="recommendations",uniqueConstraints={@UniqueConstraint(name="uq_recommendations_pair",columnNames={"request_id","place_id"}),@UniqueConstraint(name="uq_recommendations_order",columnNames={"request_id","display_order"})}) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Recommendation {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long recommendationId;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="request_id") private RecommendationRequest request;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="place_id") private Place place;@JdbcTypeCode(SqlTypes.ARRAY) @Column(columnDefinition="text[]") private String[] matchedTags;@Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(nullable=false,columnDefinition="rec_basis") private RecommendationBasis basis;@Column(nullable=false,columnDefinition="text") private String reason;@Column(nullable=false) private Short displayOrder;}
